package dev.nexus.service.db;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The tags and title patterns that mark a T2 memory row as an audit record (RDR-238).
 * {@code MemoryRepository.replaceMemory} refuses a {@code replaces} whose target carries one of
 * the tags or whose title matches one of the patterns. {@code nx memory curate --t2} reads the
 * same table on the Python side.
 *
 * <p><b>Tag rule.</b> A row's tags are one string. The rule: split on ',', trim each element (the
 * {@link String#trim()} rule: characters at or below U+0020), drop empty elements, and compare
 * each element for exact, case-sensitive equality with a member of {@link #AUDIT_TAGS}. A whole tag,
 * never a substring: {@code gates} and {@code kind:gate-x} are not audit tags, and {@code Gate} is
 * not {@code gate}. Only the tags string is read, never the row's content.
 *
 * <p><b>Title rule (the backstop for older untagged audit rows).</b> Each entry of
 * {@link #TITLE_PATTERN_SOURCES} is one regular expression, searched anywhere in the title
 * ({@code find()}, not {@code matches()}), case-insensitively and ASCII-only
 * ({@link Pattern#CASE_INSENSITIVE}, with {@link Pattern#UNIX_LINES} so that '$' matches only before a
 * final '\n', as Python's does). A token entry is a whole word bounded by the start or end of
 * the title or by '-', '_', '.', ':' or a space on each side. No entry may put a quantifier (star, plus, brace) after a
 * group: Java's regex engine recurses per character on such a group and overflows the stack.
 */
public final class AuditTags {

    private AuditTags() {}

    /** The audit tags, matched as whole tags (see the class comment). */
    public static final Set<String> AUDIT_TAGS = Set.of(
        "commit-review",
        "critique",
        "fix-check",
        "gate",
        "kind:gate",
        "research");

    /** The title patterns' source text, in table order. */
    public static final List<String> TITLE_PATTERN_SOURCES = List.of(
        "(^|[-_.: ])review([-_.: ]|$)",
        "(^|[-_.: ])code-review([-_.: ]|$)",
        "(^|[-_.: ])commit-review([-_.: ]|$)",
        "(^|[-_.: ])critique([-_.: ]|$)",
        "(^|[-_.: ])gate([-_.: ]|$)",
        "(^|[-_.: ])fix-check([-_.: ]|$)",
        "-research-[0-9]+(\\.md)?$",
        "(^|[-_.: ])confirm([-_.: ]|$)",
        "(^|[-_.: ])audit([-_.: ]|$)");

    private static final List<Pattern> TITLE_PATTERNS = TITLE_PATTERN_SOURCES.stream()
            .map(p -> Pattern.compile(p, Pattern.CASE_INSENSITIVE | Pattern.UNIX_LINES))
            .toList();

    /** The audit tags {@code tags} carries, in the order they appear (empty when none). */
    public static List<String> auditTagsOf(String tags) {
        List<String> found = new ArrayList<>();
        if (tags == null || tags.isEmpty()) {
            return found;
        }
        for (String part : tags.split(",", -1)) {
            String tag = part.trim();
            if (!tag.isEmpty() && AUDIT_TAGS.contains(tag)) {
                found.add(tag);
            }
        }
        return found;
    }

    /** The source text of the first title pattern that matches {@code title}, if any. */
    public static Optional<String> titlePatternOf(String title) {
        if (title == null || title.isEmpty()) {
            return Optional.empty();
        }
        for (int i = 0; i < TITLE_PATTERNS.size(); i++) {
            if (TITLE_PATTERNS.get(i).matcher(title).find()) {
                return Optional.of(TITLE_PATTERN_SOURCES.get(i));
            }
        }
        return Optional.empty();
    }
}
